"use client";

import React, { useState, useEffect } from 'react';
import Link from 'next/link';

export default function Navbar() {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [customer, setCustomer] = useState(null);

  useEffect(() => {
    // Check localStorage for customer auth
    const token = localStorage.getItem('auth_token');
    const customerData = localStorage.getItem('customer');
    if (token && customerData) {
      try {
        setCustomer(JSON.parse(customerData));
      } catch (e) {}
    }
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('auth_token');
    localStorage.removeItem('customer');
    setCustomer(null);
    window.location.href = '/';
  };

  return (
    <header class="sticky top-0 z-50 glass-header">
      <div class="container mx-auto px-4 py-3 flex items-center justify-between">
        {/* Brand Logo */}
        <Link href="/" class="flex items-center gap-2.5 sm:gap-3 group text-decoration-none shrink-0">
          <div class="w-9 h-9 sm:w-10 sm:h-10 rounded-xl bg-gradient-to-tr from-rose-500 to-rose-400 text-white flex items-center justify-center shadow-lg shadow-rose-500/20 group-hover:scale-105 transition-transform">
            <i class="fa-solid font-bold fa-spa text-base sm:text-lg"></i>
          </div>
          <span class="font-display font-bold text-lg sm:text-xl tracking-tight text-slate-900 group-hover:text-rose-600 transition-colors leading-tight">
            Chammy Florals
          </span>
        </Link>

        {/* Desktop Nav Items */}
        <nav class="hidden md:flex items-center gap-3">
          <Link href="/" class="btn-shadcn-ghost flex items-center gap-2 text-decoration-none text-sm px-3 py-2">
            <i class="fa fa-home text-rose-500"></i>
            <span>Home</span>
          </Link>
          <Link href="/reviews" class="btn-shadcn-ghost flex items-center gap-2 text-decoration-none text-sm px-3 py-2">
            <i class="fa fa-star text-amber-400"></i>
            <span>Reviews</span>
          </Link>
          <button
            type="button"
            onClick={() => {
              const modalEl = document.getElementById('customizeOrderModal');
              if (modalEl && window.bootstrap) {
                new window.bootstrap.Modal(modalEl).show();
              }
            }}
            class="btn-shadcn-ghost flex items-center gap-2 text-decoration-none text-sm px-3 py-2 text-slate-700"
          >
            <i class="fa fa-palette text-rose-500"></i>
            <span>Custom Order</span>
          </button>
          {customer ? (
            <div class="flex items-center gap-2">
              <Link href="/dashboard" class="btn-shadcn-primary text-decoration-none px-4 py-2 text-xs sm:text-sm font-semibold shadow-md">
                <i class="fa fa-tachometer-alt me-1.5"></i>Dashboard
              </Link>
            </div>
          ) : (
            <div class="flex items-center gap-2">
              <Link href="/login" class="btn-shadcn-primary text-decoration-none px-4 py-2 text-xs sm:text-sm font-semibold shadow-md">
                <i class="fa fa-sign-in-alt me-1.5"></i>Login
              </Link>
            </div>
          )}
        </nav>

        {/* Mobile Hamburger Button */}
        <button
          type="button"
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          aria-label="Toggle Navigation Menu"
          class="md:hidden p-2.5 rounded-xl border border-slate-200/80 bg-white/90 hover:bg-slate-100 text-slate-800 transition-all flex items-center justify-center shadow-sm"
        >
          <i class={`fa-solid ${mobileMenuOpen ? 'fa-xmark' : 'fa-bars'} text-lg text-slate-700`}></i>
        </button>
      </div>

      {/* Mobile Navigation Drawer */}
      {mobileMenuOpen && (
        <div class="md:hidden border-t border-slate-200/80 bg-white/95 backdrop-blur-2xl px-4 py-4 space-y-2.5 shadow-2xl transition-all">
          <Link
            href="/"
            onClick={() => setMobileMenuOpen(false)}
            class="flex items-center gap-3 p-3 rounded-xl bg-slate-100/90 hover:bg-slate-200/90 text-slate-800 font-semibold text-sm text-decoration-none"
          >
            <i class="fa fa-home text-rose-500 text-base"></i>
            <span>Home</span>
          </Link>
          <Link
            href="/reviews"
            onClick={() => setMobileMenuOpen(false)}
            class="flex items-center gap-3 p-3 rounded-xl bg-slate-100/90 hover:bg-slate-200/90 text-slate-800 font-semibold text-sm text-decoration-none"
          >
            <i class="fa fa-star text-amber-400 text-base"></i>
            <span>Reviews</span>
          </Link>
          <button
            type="button"
            onClick={() => {
              setMobileMenuOpen(false);
              const modalEl = document.getElementById('customizeOrderModal');
              if (modalEl && window.bootstrap) {
                new window.bootstrap.Modal(modalEl).show();
              }
            }}
            class="w-full flex items-center gap-3 p-3 rounded-xl bg-slate-100/90 hover:bg-slate-200/90 text-slate-800 font-semibold text-sm text-decoration-none text-start border-0"
          >
            <i class="fa fa-palette text-rose-500 text-base"></i>
            <span>Custom Order</span>
          </button>
          <div class="w-full pt-1">
            {customer ? (
              <Link
                href="/dashboard"
                onClick={() => setMobileMenuOpen(false)}
                class="btn-shadcn-primary text-decoration-none w-full flex items-center justify-center px-4 py-2.5 text-sm font-semibold shadow-md"
              >
                <i class="fa fa-tachometer-alt me-1.5"></i>Dashboard
              </Link>
            ) : (
              <Link
                href="/login"
                onClick={() => setMobileMenuOpen(false)}
                class="btn-shadcn-primary text-decoration-none w-full flex items-center justify-center px-4 py-2.5 text-sm font-semibold shadow-md"
              >
                <i class="fa fa-sign-in-alt me-1.5"></i>Login
              </Link>
            )}
          </div>
        </div>
      )}
    </header>
  );
}
